BEGIN;
CREATE TABLE IF NOT EXISTS customs_tenants(id UUID PRIMARY KEY,name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS customs_tenant_memberships(tenant_id UUID NOT NULL REFERENCES customs_tenants(id),user_id INTEGER NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN('analyst','compliance_reviewer','filing_officer','auditor','admin')),active BOOLEAN NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS customs_source_versions(id BIGSERIAL PRIMARY KEY,source_type TEXT NOT NULL,jurisdiction TEXT NOT NULL,version TEXT NOT NULL,effective_from TIMESTAMPTZ NOT NULL,effective_to TIMESTAMPTZ,source_uri TEXT NOT NULL,sha256 CHAR(64) NOT NULL,payload JSONB NOT NULL,UNIQUE(source_type,jurisdiction,version));
CREATE TABLE IF NOT EXISTS customs_cases(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES customs_tenants(id),external_reference TEXT NOT NULL,effective_at TIMESTAMPTZ NOT NULL,jurisdiction TEXT NOT NULL,intake_snapshot JSONB NOT NULL,intake_hash CHAR(64) NOT NULL,status TEXT NOT NULL DEFAULT'intake' CHECK(status IN('intake','classified','screened','exception_review','dual_approved','ready_to_file','rejected','filed')),idempotency_key TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 0,created_by INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS customs_decisions(id BIGSERIAL PRIMARY KEY,case_id BIGINT NOT NULL REFERENCES customs_cases(id),decision_type TEXT NOT NULL,decision TEXT NOT NULL,explanation TEXT NOT NULL,source_version_ids BIGINT[] NOT NULL,match_score NUMERIC(5,2),threshold NUMERIC(5,2),created_by INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS customs_approvals(id BIGSERIAL PRIMARY KEY,case_id BIGINT NOT NULL REFERENCES customs_cases(id),reviewer_id INTEGER NOT NULL REFERENCES users(id),decision TEXT NOT NULL,rationale TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(case_id,reviewer_id));
CREATE TABLE IF NOT EXISTS customs_filings(id BIGSERIAL PRIMARY KEY,case_id BIGINT NOT NULL UNIQUE REFERENCES customs_cases(id),payload_hash CHAR(64) NOT NULL,gateway_receipt TEXT NOT NULL UNIQUE,source_snapshot JSONB NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE OR REPLACE FUNCTION customs_filings_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'customs filings are immutable'; END $$;
DROP TRIGGER IF EXISTS customs_filings_no_change ON customs_filings;
CREATE TRIGGER customs_filings_no_change BEFORE UPDATE OR DELETE ON customs_filings FOR EACH ROW EXECUTE FUNCTION customs_filings_immutable();
CREATE TABLE IF NOT EXISTS customs_provider_syncs(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES customs_tenants(id),provider TEXT NOT NULL,cursor TEXT,status TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,failure_code TEXT,failure_detail TEXT,source_version TEXT,started_at TIMESTAMPTZ,completed_at TIMESTAMPTZ,UNIQUE(tenant_id,provider,cursor));
CREATE TABLE IF NOT EXISTS customs_audit_events(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES customs_tenants(id),case_id BIGINT REFERENCES customs_cases(id),actor_id INTEGER REFERENCES users(id),action TEXT NOT NULL,payload JSONB NOT NULL,occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS customs_cases_queue_idx ON customs_cases(tenant_id,status,updated_at);
COMMIT;
